import pytest

# Generated by find_examples.py from real rows of data/data.csv.
# Each case: (name, request body, risk level the model predicts)
CASES = [
    ('high_1', {'latitude': -22.99448, 'longitude': -43.289465, 'elevation_m': -3.0, 'land_use': 'Residential', 'soil_group': None, 'drainage_density_km_per_km2': 2.19, 'storm_drain_proximity_m': 36.6, 'storm_drain_type': 'OpenChannel', 'historical_rainfall_intensity_mm_hr': 52.0, 'return_period_years': 2.0}, 'High'),  # confidence 1.00
    ('high_2', {'latitude': 14.672318, 'longitude': 120.987996, 'elevation_m': 2.07, 'land_use': 'Institutional', 'soil_group': 'D', 'drainage_density_km_per_km2': 4.65, 'storm_drain_proximity_m': 209.0, 'storm_drain_type': 'GratedInlet', 'historical_rainfall_intensity_mm_hr': 110.7, 'return_period_years': 25.0}, 'High'),  # confidence 1.00
    ('moderate_1', {'latitude': 52.480152, 'longitude': 4.750103, 'elevation_m': 1.61, 'land_use': 'Residential', 'soil_group': 'B', 'drainage_density_km_per_km2': 8.26, 'storm_drain_proximity_m': 363.5, 'storm_drain_type': None, 'historical_rainfall_intensity_mm_hr': 42.8, 'return_period_years': 10.0}, 'Moderate'),  # confidence 1.00
    ('moderate_2', {'latitude': 51.868593, 'longitude': 4.420131, 'elevation_m': 7.27, 'land_use': 'Roads', 'soil_group': None, 'drainage_density_km_per_km2': 10.09, 'storm_drain_proximity_m': 252.9, 'storm_drain_type': None, 'historical_rainfall_intensity_mm_hr': 27.3, 'return_period_years': 2.0}, 'Moderate'),  # confidence 1.00
    ('low_1', {'latitude': 39.859241, 'longitude': -75.12075, 'elevation_m': 66.53, 'land_use': 'Water', 'soil_group': 'C', 'drainage_density_km_per_km2': 5.92, 'storm_drain_proximity_m': 291.4, 'storm_drain_type': 'GratedInlet', 'historical_rainfall_intensity_mm_hr': 36.8, 'return_period_years': 2.0}, 'Low'),  # confidence 1.00
    ('low_2', {'latitude': 41.870449, 'longitude': 12.537356, 'elevation_m': 81.34, 'land_use': 'Mixed', 'soil_group': 'C', 'drainage_density_km_per_km2': 8.12, 'storm_drain_proximity_m': 81.2, 'storm_drain_type': 'CurbInlet', 'historical_rainfall_intensity_mm_hr': 33.9, 'return_period_years': 25.0}, 'Low'),  # confidence 1.00
]

@pytest.mark.parametrize("name,payload,expected", CASES, ids=[c[0] for c in CASES])
def test_predict_input_condition(client, name, payload, expected):
    r = client.post("/predict", json=payload)
    assert r.status_code == 200
    body = r.json()
    assert body["risk_level"] == expected
    assert set(body["probabilities"]) == {"High", "Moderate", "Low"}
    assert abs(sum(body["probabilities"].values()) - 1) < 0.01
    assert body["confidence"] == max(body["probabilities"].values())
